callout('Un affichage saccadé ne signifie pas automatiquement que le serveur OpenSimulator fonctionne mal : le viewer, le PC, la connexion et la région ont chacun leur rôle.','Choppy graphics do not automatically mean OpenSimulator is lagging: the viewer, PC, internet connection and region each play a role.');
echo '<nav class="install-toc"><strong>'.e(t('Dans ce chapitre','In this chapter')).'</strong><ul>';
