echo '<li><a href="#fire-12">'.e(t('Contrôle rapide en une minute','One-minute diagnostic checklist')).'</a></li>';
echo '</ul></nav>';
echo '<section class="install-entry"><h2>'.e(t('Identifier le problème selon les symptômes','Identify the problem by symptoms')).'</h2>';
$symptoms=[
['FPS faibles, scripts réactifs','Low FPS, responsive scripts','Rendu local, GPU, options graphiques','Local rendering, GPU, graphics settings','Tester 64–128 m et désactiver les ombres','Try 64–128 m and disable shadows'],
['Textures grises ou floues','Gray or blurry textures','Téléchargement des assets, réseau ou cache','Asset downloads, network or cache','Attendre, vérifier réseau, relancer','Wait, test network, relog'],
['Mouvements saccadés','Jerky movement','Perte de paquets, ping ou jitter','Packet loss, ping or jitter','Comparer Ethernet et Wi-Fi ; stats viewer','Compare wired/Wi-Fi and viewer stats'],
['Scripts lents pour plusieurs personnes','Slow scripts for multiple people','Simulateur, physique, scripts ou réseau','Simulator, physics, scripts or network','Comparer autres régions et consulter les logs','Compare regions and check logs']
];
echo '<div class="overflow"><table><thead><tr><th>'.e(t('Symptôme','Symptom')).'</th><th>'.e(t('Cause à examiner','Possible cause')).'</th><th>'.e(t('Premier test','First test')).'</th></tr></thead><tbody>';
